]
train_with_callbacks(model, optimizer, train_loader, val_loader, epochs=50, callbacks=callbacks)

import copy
import torch
import torch.nn as nn

class EMA:
    def __init__(self, model, decay=0.999):
        self.decay = decay
        self.shadow = copy.deepcopy(model)  # a separate, frozen copy of the model
        for p in self.shadow.parameters():
            p.requires_grad = False

    @torch.no_grad()
    def update(self, model):
        for shadow_p, model_p in zip(self.shadow.parameters(), model.parameters()):
            shadow_p.data.mul_(self.decay).add_(model_p.data, alpha=1 - self.decay)
        # Also sync buffers (e.g. BatchNorm running stats) directly, no averaging needed
        for shadow_b, model_b in zip(self.shadow.buffers(), model.buffers()):
            shadow_b.data.copy_(model_b.data)

    def state_dict(self):
        return self.shadow.state_dict()


# Usage in a training loop
model = nn.Sequential(nn.Linear(20, 64), nn.ReLU(), nn.Linear(64, 10))
optimizer = torch.optim.Adam(model.parameters(), lr=1e-3)
ema = EMA(model, decay=0.999)

for epoch in range(num_epochs):
    model.train()
    for x, y in train_loader:
        optimizer.zero_grad()
        loss = nn.functional.cross_entropy(model(x), y)
        loss.backward()
        optimizer.step()
        ema.update(model)  # smooth-update the shadow weights after every step

    # Evaluate using the EMA model instead of the raw training model
    ema.shadow.eval()
    with torch.no_grad():
        val_loss = sum(
            nn.functional.cross_entropy(ema.shadow(x), y).item()
            for x, y in val_loader
        ) / len(val_loader)
    print(f"Epoch {epoch}: EMA val_loss = {val_loss:.4f}")
